254	        if (!claim.getStatus().canMoveTo(next) || next == ClaimStatus.PENDING
255	                || (next == ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.OPEN)
256	                || (next == ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.DRAFT)) {
257	            throw new ResponseStatusException(HttpStatus.CONFLICT,
258	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
259	        }
260	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.load(sheetId).getToday())) {
261	            throw new ResponseStatusException(HttpStatus.CONFLICT,
262	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
263	        }
264	        if (next == ClaimStatus.SETTLED && by.equals(claim.getOpenedBy())) {
265	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who opened a claim cannot settle it.");
266	        }
267	        if (next == ClaimStatus.SETTLED && by.equals(claim.getEditedBy())) {
268	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who last edited a claim cannot settle it.");
269	        }
270	        if (next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
271	            refuseVoidOfSettled(by, sheetId, claim);
272	            // the frozen figure leaves every total; the claim keeps its number and shows the figure it had
273	            tail = " reversed=" + text(claim.getSettledDue());
274	        }
275	        if (next == ClaimStatus.VOID) {
276	            String voidReason = voidReasons.refuseUnlessListed(sheetId, reason);
277	            claim.setVoidReason(voidReason);
278	            if (voidReason != null) {
279	                tail += " reason=" + voidReason;
280	            }
281	        }
282	        if (next == ClaimStatus.OPEN) {
283	            refuseWithoutNote(sheetId, claim);
284	            number(sheetId, claim);
285	            claim.setOpenedBy(by);
286	        }
287	        Person person = person(sheetId, claim.getPersonId());
288	        String event = switch (next) {
289	            case OPEN -> "CLAIM_OPENED";
290	            case SETTLED -> "CLAIM_SETTLED";
291	            case VOID -> "CLAIM_VOIDED";
292	            case DRAFT, PENDING, DELETED -> throw new IllegalStateException();
293	        };
294	        if (next == ClaimStatus.SETTLED) {
295	            // the due is fixed at the figure a statement bound it to, else at the rate the person's grade has in
296	            // force on the claim's date, with the late charge it has gained by today, and at least the floor in force
297	            // on its date; with none it stays live
298	            BigDecimal figure = claim.isStated() && claim.getStatedDue() != null ? claim.getStatedDue()
299	                    : rateFigure(sheetId, person, claim);
300	            BigDecimal fixed = liveDue(figure, claim, person, sheets.load(sheetId), true);
301	            refuseWithoutProof(sheetId, claim, fixed);
302	            if (settings.aboveClerkLimit(sheetId, by, fixed)) {
303	                next = ClaimStatus.PENDING;
304	                event = "CLAIM_PENDING";
305	            } else {
306	                claim.setSettledDue(fixed);
307	                tail = " due=" + (fixed == null ? "n/a" : fixed.toPlainString());
308	            }
309	        }
310	        claim.setStatus(next);
311	        logStatus(by, sheetId, person, claim);
312	        Claim saved = claims.saveAndFlush(claim);
313	        audit.recordOnCommit(record(event, by, person, saved) + tail);
314	        if (next == ClaimStatus.SETTLED) {
315	            watches.notifyWatchers(by, sheetId, person, saved.getNumber());
316	        }
317	        rollup.recordChanges(by, sheetId, before);
318	        return saved;
319	    }
