321	    /**
322	     * Deletes a DRAFT claim: it is DELETED, counts nowhere and can no longer be edited, opened or voided. Refused
323	     * for a claim in any other status, one another user's editor holds, and in a closed period.
324	     */
325	    @Transactional
326	    public Claim delete(String by, String sheetId, Long id) {
327	        Claim claim = lockedClaim(sheetId, id);
328	        if (claim.getStatus() != ClaimStatus.DRAFT) {
329	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a DRAFT claim can be deleted.");
330	        }
331	        refuseLockedByOther(by, claim);
332	        RollupService.Snapshot before = rollup.snapshot(sheetId);
333	        Person person = person(sheetId, claim.getPersonId());
334	        claim.setStatus(ClaimStatus.DELETED);
335	        claim.setLockedBy(null);
336	        logStatus(by, sheetId, person, claim);
337	        Claim saved = claims.saveAndFlush(claim);
338	        audit.recordOnCommit(record("CLAIM_DELETED", by, person, saved));
339	        rollup.recordChanges(by, sheetId, before);
340	        return saved;
341	    }
