343	    /**
344	     * Restores a DELETED claim to a DRAFT again. Refused for a claim that is not DELETED, unless the sheet's today is
345	     * the one it was deleted on, and in a closed period.
346	     */
347	    @Transactional
348	    public Claim restore(String by, String sheetId, Long id) {
349	        Claim claim = lockedClaim(sheetId, id);
350	        if (claim.getStatus() != ClaimStatus.DELETED) {
351	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a DELETED claim can be restored.");
352	        }
353	        LocalDate today = sheets.load(sheetId).getToday();
354	        LocalDate deletedOn = claim.deletedOn();
355	        if (deletedOn == null ? today != null : !deletedOn.equals(today)) {
356	            throw new ResponseStatusException(HttpStatus.CONFLICT,
357	                    "A claim can only be restored on the day it was deleted.");
358	        }
359	        RollupService.Snapshot before = rollup.snapshot(sheetId);
360	        Person person = person(sheetId, claim.getPersonId());
361	        claim.setStatus(ClaimStatus.DRAFT);
362	        logStatus(by, sheetId, person, claim);
363	        Claim saved = claims.saveAndFlush(claim);
364	        audit.recordOnCommit(record("CLAIM_RESTORED", by, person, saved));
365	        rollup.recordChanges(by, sheetId, before);
366	        return saved;
367	    }
