369	    /**
370	     * Defers an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim counts
371	     * in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a claim that is
372	     * not OPEN, a date not after today, and in a closed period.
373	     */
374	    @Transactional
375	    public Claim defer(String by, String sheetId, Long id, LocalDate until) {
376	        Claim claim = lockedClaim(sheetId, id);
377	        if (claim.getStatus() != ClaimStatus.OPEN) {
378	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be deferred.");
379	        }
380	        LocalDate today = sheets.load(sheetId).getToday();
381	        if (until == null || (today != null && !until.isAfter(today))) {
382	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
383	                    "A claim can only be deferred to a date after the sheet's today.");
384	        }
385	        RollupService.Snapshot before = rollup.snapshot(sheetId);
386	        claim.setDeferredUntil(until, today);
387	        Claim saved = claims.saveAndFlush(claim);
388	        audit.recordOnCommit(record("CLAIM_DEFERRED", by, person(sheetId, saved.getPersonId()), saved) + " until="
389	                + until);
390	        rollup.recordChanges(by, sheetId, before);
391	        return saved;
392	    }
393	
394	    /**
395	     * Writes a reminder for an OPEN or PENDING claim, which shows the sheet's today as its reminded date. Refused for
396	     * a claim in any other status and one already reminded on the sheet's today; a reminder changes none of the
397	     * claim's figures, so one whose due-by falls in a closed period may still be reminded.
398	     */
399	    @Transactional
400	    public Claim remind(String by, String sheetId, Long id) {
401	        sheets.lock(sheetId);
402	        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
403	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
404	        if (!claim.getStatus().isOpen()) {
405	            throw new ResponseStatusException(HttpStatus.CONFLICT,
406	                    "A " + claim.getStatus() + " claim cannot be reminded.");
407	        }
408	        LocalDate today = sheets.load(sheetId).getToday();
409	        if (today != null && today.equals(claim.getRemindedOn())) {
410	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded today.");
411	        }
412	        claim.setRemindedOn(today);
413	        Claim saved = claims.saveAndFlush(claim);
414	        audit.recordOnCommit(record("REMIND", by, person(sheetId, saved.getPersonId()), saved));
415	        return saved;
416	    }
417	
418	    /** Adds a comment to the claim, by the user on the sheet's today. Refused for a blank comment. */
419	    @Transactional
420	    public Claim comment(String by, String sheetId, Long id, String text) {
421	        String stripped = text == null ? "" : text.strip();
422	        if (stripped.isEmpty()) {
423	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A comment cannot be empty.");
424	        }
425	        sheets.lock(sheetId);
426	        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
427	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
428	        claim.comment(by, sheets.load(sheetId).getToday(), stripped);
429	        Claim saved = claims.saveAndFlush(claim);
