435	    /**
436	     * Raises the claim's proofs count by one. Refused for a SETTLED, VOID or DELETED claim, and in a closed period.
437	     */
438	    @Transactional
439	    public Claim addProof(String by, String sheetId, Long id) {
440	        Claim claim = lockedClaim(sheetId, id);
441	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
442	                || claim.getStatus() == ClaimStatus.DELETED) {
443	            throw new ResponseStatusException(HttpStatus.CONFLICT,
444	                    "A " + claim.getStatus() + " claim cannot take a proof.");
445	        }
446	        claim.addProof();
447	        Claim saved = claims.saveAndFlush(claim);
448	        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", by, person(sheetId, saved.getPersonId()), saved)
449	                + " proofs=" + saved.getProofs());
450	        return saved;
451	    }
