453	    /**
454	     * Refuses settling or approving the claim at the due (null for n/a) when the due is above the proof threshold in
455	     * force on the claim's date (its person's grade's then when one is set, else the sheet's) and the claim has no
456	     * proof; an n/a due is within any threshold.
457	     */
458	    private void refuseWithoutProof(String sheetId, Claim claim, BigDecimal due) {
459	        String grade = person(sheetId, claim.getPersonId()).gradeOn(claim.getDate());
460	        BigDecimal threshold = sheets.load(sheetId).proofThresholdFor(grade, claim.getDate());
461	        if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
462	            throw new ResponseStatusException(HttpStatus.CONFLICT,
463	                    "A claim with a due above " + threshold.toPlainString() + " needs a proof first.");
464	        }
465	    }
