468	     * Refuses opening the claim when its note is empty and its due is above the note threshold in force on its date;
469	     * an n/a due is within any threshold.
470	     */
471	    private void refuseWithoutNote(String sheetId, Claim claim) {
472	        BigDecimal threshold = sheets.load(sheetId).noteThresholdOn(claim.getDate());
473	        if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
474	            return;
475	        }
476	        BigDecimal due = due(sheetId, person(sheetId, claim.getPersonId()), claim);
477	        if (due != null && due.compareTo(threshold) > 0) {
478	            throw new ResponseStatusException(HttpStatus.CONFLICT,
479	                    "A claim with a due above " + threshold.toPlainString() + " needs a note first.");
480	        }
