625	     * A steward re-dates an OPEN or PENDING claim. Its due-by, and so its period and number, stay as they were fixed
626	     * and a figure a statement bound it to stays bound; its rounding (unless a correction) follows the new date.
627	     * Refused unless the user is a steward, for a claim that is not OPEN or PENDING, for a claim whose due-by falls
628	     * in a closed period, and for a new date after the person's retirement.
629	     */
630	    @Transactional
631	    public Claim redate(String by, String sheetId, Long id, LocalDate date) {
632	        if (!settings.isSteward(sheetId, by)) {
633	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-date a claim.");
634	        }
635	        Claim claim = lockedClaim(sheetId, id);
636	        if (!claim.getStatus().isOpen()) {
637	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim cannot be re-dated.");
638	        }
639	        Person person = person(sheetId, claim.getPersonId());
640	        refuseAfterRetirement(person, date);
641	        RollupService.Snapshot before = rollup.snapshot(sheetId);
642	        LocalDate old = claim.getDate();
643	        claim.setDate(date);
644	        if (!claim.isCorrection()) {
645	            claim.setRoundsOn(date);
646	        }
647	        Claim saved = claims.saveAndFlush(claim);
648	        audit.recordOnCommit(record("CLAIM_REDATED", by, person, saved) + " old=" + old + " new=" + date);
649	        rollup.recordChanges(by, sheetId, before);
650	        return saved;
651	    }
652	
653	    /** An OPEN claim after a split, and the new OPEN claim split off it. */
654	    public record Split(Claim original, Claim split) {
655	    }
656	
657	    /**
658	     * Splits an amount (more than 0.00 and less than the claim's) off an OPEN claim: the claim keeps the rest and
659	     * loses any figure a statement bound it to; a new OPEN claim with the amount, the same date and note, the next
660	     * number, opened by the user, with a due-by from the terms in force on the date, and split from the original's
661	     * number, and a late entry when the original is, is listed as its person's newest. Refused unless the user's
662	     * role may open a claim, for a claim that is not OPEN or is deferred, for an amount out of range, and when the
663	     * original's due-by falls in a closed period (the new claim's own due-by is not judged).
664	     */
665	    @Transactional
666	    public Split split(String by, String sheetId, Long id, BigDecimal amount) {
667	        settings.refuseUnlessMay(sheetId, by, "open");
668	        Claim claim = lockedClaim(sheetId, id);
669	        if (claim.getStatus() != ClaimStatus.OPEN) {
670	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be split.");
671	        }
672	        if (claim.isDeferredOn(sheets.load(sheetId).getToday())) {
673	            throw new ResponseStatusException(HttpStatus.CONFLICT,
674	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
675	        }
676	        if (amount == null || amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
677	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
