570	  constructor() {
571	    // The store says which claim this user's editor holds: a re-read sheet shows it open again, and an editor whose
572	    // claim it no longer holds (released when the sheet's today changed) is closed.
573	    effect(() => {
574	      const user = this.session.user();
575	      const claims = this.claims();
576	      untracked(() => {
577	        const editing = this.editingId();
578	        const mine = claims.find((c) => c.lockedBy !== null && c.lockedBy === user);
579	        if (editing !== null && !this.locking && claims.some((c) => c.id === editing && c.lockedBy !== user)) {
580	          this.reset();
581	        }
582	        if (this.editingId() === null && mine) this.openEditor(mine);
583	      });
584	    });
585	    // A today change releases every claim, so an open editor is closed with it.
586	    let today: string | null | undefined;
587	    effect(() => {
588	      const now = this.session.sheetToday();
589	      if (today !== undefined && now !== today) untracked(() => this.reset());
590	      today = now;
591	    });
592	  }
