620	  protected async edit(c: Claim): Promise<void> {
621	    this.clearRowError(c.id);
622	    const sheet = this.session.sheetId();
623	    if (!sheet) return;
624	    const user = this.session.user();
625	    // a viewer is refused by the store, which knows whether a delegation lets them act
626	    if (this.session.sheetArchived()) {
627	      this.setRowError(c.id, 'Your role may not edit a claim on this sheet.');
628	      return;
629	    }
630	    if (c.status !== 'DRAFT') {
631	      // an open claim is changed by voiding it and adding a new one
632	      this.setRowError(c.id, `A ${c.status} claim cannot be edited; only a draft can. Void it and add a new one.`);
633	      return;
634	    }
635	    if (inClosedPeriod(this.periods.list(), c.dueBy)) {
636	      this.setRowError(c.id, CLOSED);
637	      return;
638	    }
639	    if (c.lockedBy !== null && c.lockedBy !== user) {
640	      this.setRowError(c.id, LOCKED);
641	      return;
642	    }
643	    const was = this.editingId();
644	    this.openEditor(c);
645	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/lock`;
646	    const locking = firstValueFrom(this.http.post<Claim>(url, null)).then(
647	      (held) => {
648	        // the store released the claim this user's editor held before
649	        const prev = was !== null && was !== c.id ? this.claims().find((x) => x.id === was) : undefined;
650	        if (prev) this.saved.emit({ ...prev, lockedBy: null });
651	        this.saved.emit(held);
652	        return true;
653	      },
654	      (e: unknown) => {
655	        this.refuseEdit(c, e);
656	        return false;
657	      },
658	    );
659	    this.locking = locking;
660	    await locking;
661	    if (this.locking === locking) this.locking = null;
662	  }
