670	  protected async saveInline(c: Claim): Promise<void> {
671	    this.clearRowError(c.id);
672	    const sheet = this.session.sheetId();
673	    if (!sheet) return;
674	    const user = this.session.user();
675	    // a viewer is refused by the store, which knows whether a delegation lets them act
676	    if (this.session.sheetArchived()) {
677	      this.setRowError(c.id, 'Your role may not edit a claim on this sheet.');
678	      return;
679	    }
680	    const amount = (this.inlineAmounts()[c.id] ?? '').trim();
681	    if (!SIGNED_AMOUNT.test(amount)) {
682	      this.setRowError(c.id, 'Enter an amount with up to two decimals.');
683	      return;
684	    }
685	    const correction = amount.startsWith('-');
686	    if (correction && !c.corrects) {
687	      this.setRowError(c.id, 'A negative amount is a correction: enter the number of the settled claim it corrects.');
688	      return;
689	    }
690	    if (c.status !== 'DRAFT') {
691	      this.setRowError(c.id, `A ${c.status} claim cannot be edited; only a draft can. Void it and add a new one.`);
692	      return;
693	    }
694	    if (inClosedPeriod(this.periods.list(), c.dueBy)) {
695	      this.setRowError(c.id, CLOSED);
696	      return;
697	    }
698	    if (c.lockedBy !== null && c.lockedBy !== user) {
699	      this.setRowError(c.id, LOCKED);
700	      return;
701	    }
702	    const retiredFrom = this.retiredFrom();
703	    if (retiredFrom !== null && c.date > retiredFrom) {
704	      this.setRowError(c.id, `${this.personName()} is retired from ${retiredFrom}, so a claim cannot be dated after it.`);
705	      return;
706	    }
