710	      return;
711	    }
712	    const form = { amount, date: c.date, note: c.note, corrects: correction ? c.corrects : null, ref: c.ref, tags: c.tags.join(',') };
713	    try {
714	      const saved = await firstValueFrom(
715	        this.http.put<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}`, form),
716	      );
717	      this.saved.emit(saved);
718	      this.inlineAmounts.update(({ [c.id]: _, ...rest }) => rest);
719	    } catch (e) {
720	      const status = e instanceof HttpErrorResponse ? e.status : 0;
721	      this.setRowError(
722	        c.id,
723	        status === 403
724	          ? 'Your role may not edit a claim on this sheet.'
725	          : status === 423
726	            ? LOCKED
727	            : `This ${c.status} claim cannot be edited, or its period is closed.`,
728	      );
729	    }
730	  }
