765	  protected async act(c: Claim, action: ClaimAction): Promise<void> {
766	    this.clearRowError(c.id);
767	    const sheet = this.session.sheetId();
768	    if (!sheet) return;
769	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/${action}`;
770	    if (inClosedPeriod(this.periods.list(), c.dueBy)) {
771	      this.setRowError(c.id, CLOSED);
772	      return;
773	    }
774	    const reason = (this.rejectReasons()[c.id] ?? '').trim();
775	    if (action === 'reject' && !reason) {
776	      this.setRowError(c.id, 'Enter a reason to reject this claim.');
777	      return;
778	    }
779	    const voidReason = this.voidReasonChoices()[c.id] ?? '';
780	    const listed = this.voidReasons.list();
781	    if (action === 'void' && listed.length > 0 && !listed.some((r) => r.reason === voidReason)) {
782	      this.setRowError(c.id, 'Choose a reason from the list to void this claim.');
783	      return;
784	    }
785	    try {
786	      const body = action === 'reject' ? { reason } : action === 'void' ? { reason: voidReason || null } : null;
787	      this.saved.emit(await firstValueFrom(this.http.post<Claim>(url, body)));
788	      if (action === 'reject') this.rejectReasons.update(({ [c.id]: _, ...rest }) => rest);
789	      if (action === 'void') this.voidReasonChoices.update(({ [c.id]: _, ...rest }) => rest);
790	    } catch (e) {
791	      const opener = c.openedBy !== null && c.openedBy === this.session.user();
792	      const editor = c.editedBy !== null && c.editedBy === this.session.user();
793	      const forbidden = e instanceof HttpErrorResponse && e.status === 403;
794	      const err =
795	        action === 'delete' && c.status !== 'DRAFT'
796	          ? `A ${c.status} claim cannot be deleted; only a draft can.`
797	          : action === 'restore' && c.status === 'DELETED'
798	          ? 'A deleted claim can only be restored on the day it was deleted.'
799	          : action === 'restore'
800	          ? `A ${c.status} claim cannot be restored; only a deleted one can.`
801	          : action === 'settle' && deferred(c, this.session.sheetToday())
802	          ? `This claim is deferred until ${c.deferredUntil}, so it cannot be settled yet.`
803	          : action === 'void' && e instanceof HttpErrorResponse && e.status === 422
804	          ? 'Choose a reason from the list to void this claim.'
805	          : action === 'void' && c.status === 'SETTLED'
806	          ? 'Only a steward can void a settled claim, and only within 7 days of its settlement.'
807	          : (action === 'open' || action === 'settle' || action === 'void') && forbidden
808	          ? `Your role may not ${action} a claim on this sheet.`
809	          : action === 'settle' && opener
810	          ? 'You opened this claim, so another user must settle it.'
811	          : action === 'settle' && editor
812	          ? 'You last edited this claim, so another user must settle it.'
813	          : (action === 'approve' || action === 'reject') && forbidden
814	            ? 'Only a steward can approve or reject a pending claim.'
815	            : action === 'resettle' && forbidden
816	              ? 'Only a steward can re-settle a claim.'
817	              : action === 'approve' && opener
818	                ? 'You opened this claim, so another steward must approve it.'
819	                : action === 'approve' && editor
820	                ? 'You last edited this claim, so another steward must approve it.'
821	                : ((action === 'settle' && c.status === 'OPEN') || (action === 'approve' && c.status === 'PENDING')) &&
822	                    c.proofs === 0
823	                  ? 'This claim\'s due is above the proof threshold, so it needs a proof first.'
824	                  : `A ${c.status} claim cannot be changed that way, or its period is closed.`;
825	      this.setRowError(c.id, err);
826	    }
827	  }
